import { readFile, writeFile, rename } from 'node:fs/promises';
import path from 'node:path';
export class FileLedger {
  constructor(directory, beforeCommit = async () => {}) {
    this.file = path.join(directory, 'receipts.json');
    this.beforeCommit = beforeCommit;
    this.tail = Promise.resolve();
  }
  async readAll() {
    try { return JSON.parse(await readFile(this.file, 'utf8')); }
    catch (error) { if (error.code === 'ENOENT') return {}; throw error; }
  }
  commit(id, amountCents) {
    const operation = this.tail.then(async () => {
      await this.beforeCommit();
      const receipts = await this.readAll();
      if (receipts[id]) {
        if (receipts[id].amountCents !== amountCents) throw new Error('Receipt amount conflict');
        return receipts[id];
      }
      const receipt = { id, amountCents, state: 'paid' };
      receipts[id] = receipt;
      await writeFile(this.file + '.tmp', JSON.stringify(receipts));
      await rename(this.file + '.tmp', this.file);
      return receipt;
    });
    this.tail = operation.catch(() => {});
    return operation;
  }
  whenIdle() { return this.tail; }
}

