export function createReceiptService(ledger, onBackgroundError = () => {}) {
  return {
    async record({ id, amountCents }) {
      if (typeof id !== 'string' || !/^[a-z0-9-]+$/.test(id) || !Number.isSafeInteger(amountCents) || amountCents <= 0) {
        return { status: 400, body: { error: 'Invalid receipt' } };
      }
      try {
        await ledger.commit(id, amountCents);
        return { status: 200, body: { id, state: 'paid' } };
      } catch {
        return { status: 503, body: { id, error: 'Receipt not persisted' } };
      }
    }
  };
}

