import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { FileLedger } from '../src/file-ledger.mjs';
import { createReceiptService } from '../src/receipt-service.mjs';
const directory = await mkdtemp(path.join(tmpdir(), 'synthetic-receipt-'));
let release = () => {};
let ledger;
try {
  if (process.argv[2] === 'fail-write') {
    ledger = new FileLedger(directory, async () => { throw new Error('Synthetic EIO'); });
    const response = await createReceiptService(ledger).record({ id: 'r-1', amountCents: 700 });
    await ledger.whenIdle();
    assert.equal(response.status, 503, 'write failure must not report paid');
    assert.deepEqual(await ledger.readAll(), {});
  } else {
    const gate = new Promise((resolve) => { release = resolve; });
    ledger = new FileLedger(directory, () => gate);
    let responseSettled = false;
    const response = createReceiptService(ledger).record({ id: 'r-1', amountCents: 700 });
    response.then(() => { responseSettled = true; });
    await new Promise((resolve) => setImmediate(resolve));
    assert.deepEqual(await ledger.readAll(), {});
    assert.equal(responseSettled, false, 'paid response must wait for file persistence');
    release();
    assert.equal((await response).status, 200);
    assert.equal((await ledger.readAll())['r-1'].state, 'paid');
  }
} finally {
  release();
  await ledger?.whenIdle();
  await rm(directory, { recursive: true, force: true });
}

