const catalog = new Map([['coffee', 1200], ['tea', 800]]);
export function quoteOrder({ items, member = false }) {
  if (!Array.isArray(items) || items.length === 0) throw new Error('Empty order');
  let subtotalCents = 0;
  for (const { sku, quantity } of items) {
    if (!catalog.has(sku)) throw new Error('Unknown SKU');
    if (!Number.isSafeInteger(quantity) || quantity < 1 || quantity > 99) throw new Error('Invalid quantity');
    subtotalCents += catalog.get(sku) * quantity;
  }
  const discountCents = member ? Math.floor(subtotalCents / 10) : 0;
  const afterDiscountCents = subtotalCents - discountCents;
  const shippingCents = afterDiscountCents >= 5000 ? 0 : 499;
  return { subtotalCents, discountCents, shippingCents, totalCents: afterDiscountCents + shippingCents };
}

