import { mkdir, readFile, writeFile, rename } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import path from 'node:path';
export class FileJobs {
  constructor(root) { this.root = root; }
  file(id) {
    if (!/^[a-f0-9-]+$/.test(id)) throw new Error('Invalid job id');
    return path.join(this.root, id + '.json');
  }
  async create(tenantId, rows) {
    await mkdir(this.root, { recursive: true });
    const job = { id: randomUUID(), tenantId, rows, state: 'queued', artifact: null, error: null };
    await writeFile(this.file(job.id), JSON.stringify(job), { flag: 'wx' });
    return job;
  }
  async read(id) {
    try { return JSON.parse(await readFile(this.file(id), 'utf8')); }
    catch (error) { if (error.code === 'ENOENT') return null; throw error; }
  }
  async transition(id, expected, next, fields = {}) {
    const job = await this.read(id);
    if (!job || job.state !== expected) throw new Error('Invalid transition');
    const updated = { ...job, ...fields, state: next };
    await writeFile(this.file(id) + '.tmp', JSON.stringify(updated));
    await rename(this.file(id) + '.tmp', this.file(id));
    return updated;
  }
  async saveArtifact(id, csv) {
    const file = this.file(id).replace(/\.json$/, '.csv');
    await writeFile(file, csv);
    return path.basename(file);
  }
}

