export async function requestExport({ tenantId, rows }, jobs) {
  if (typeof tenantId !== 'string' || !tenantId || !Array.isArray(rows) || rows.length === 0 ||
      rows.some((row) => typeof row.name !== 'string' || !Number.isSafeInteger(row.cents))) {
    return { status: 400, body: { error: 'Invalid export request' } };
  }
  const job = await jobs.create(tenantId, rows);
  return { status: 202, body: { id: job.id, state: job.state } };
}
export async function getExport({ tenantId, id }, jobs) {
  const job = await jobs.read(id);
  if (!job || job.tenantId !== tenantId) return { status: 404, body: { error: 'Not found' } };
  return { status: 200, body: { id: job.id, state: job.state, artifact: job.artifact, error: job.error } };
}

