import { renderCsv } from '../../packages/export/render.mjs';
export async function runOne(jobs, id, render = renderCsv) {
  const job = await jobs.read(id);
  if (!job) throw new Error('Unknown job');
  if (job.state !== 'queued') return job;
  await jobs.transition(id, 'queued', 'running');
  try {
    const artifact = await jobs.saveArtifact(id, render(job.rows));
    return await jobs.transition(id, 'running', 'complete', { artifact });
  } catch (error) {
    return jobs.transition(id, 'running', 'failed', { error: error.message });
  }
}

