export function exportView(response) {
  if (response.status !== 200) return { heading: 'Export unavailable', action: null };
  const job = response.body;
  if (job.state === 'queued' || job.state === 'running') return { heading: 'Preparing export', action: null };
  if (job.state === 'complete') return { heading: 'Export ready', action: { label: 'Download', artifact: job.artifact } };
  return { heading: 'Export failed', action: null };
}

