import { mkdir, readdir, readFile, writeFile, rename } from 'node:fs/promises';
import path from 'node:path';
function location(root, id) {
  if (!/^[a-z0-9-]+$/.test(id)) throw new Error('Invalid message id');
  return path.join(root, id + '.json');
}
export async function enqueue(root, message) {
  await mkdir(root, { recursive: true });
  await writeFile(location(root, message.id), JSON.stringify({ ...message, state: 'pending' }), { flag: 'wx' });
}
export async function readMessage(root, id) {
  return JSON.parse(await readFile(location(root, id), 'utf8'));
}
export async function pending(root) {
  let names;
  try { names = await readdir(root); } catch (error) { if (error.code === 'ENOENT') return []; throw error; }
  const messages = await Promise.all(names.filter((name) => name.endsWith('.json')).sort().map((name) => readMessage(root, name.slice(0, -5))));
  return messages.filter((message) => message.state === 'pending');
}
export async function acknowledge(root, id) {
  const message = await readMessage(root, id);
  await writeFile(location(root, id) + '.tmp', JSON.stringify({ ...message, state: 'delivered' }));
  await rename(location(root, id) + '.tmp', location(root, id));
}

